function Lucky_Ajax_QQinfo($src) {    			 	 	 
    global $zbp;    	 	 	  	
    if ($src === 'qqinfo') {          	 
        $data = array();     				 	 
        $qq = GetVars('qq', 'GET');    			  		 
        if (!is_numeric($qq)) {    	  	    
        	return;    		  		 	
        }    	 			  	
        $data['QQ'] = $qq;    	  		  	
        $result = json_decode(Lucky_Ajax_QQinfo_Http($qq));      	  	  
        $data['info'] = isset($result->$qq) ? $result->$qq : '';    	 	  	 	
        JsonReturn($data);      	 		  
    }    	 	  	 	
}    			  	 	
    	  				 
function Lucky_Ajax_QQinfo_Http($qq) {      	     
    $http_post = Network::Create();      	  			
    $http_post->open('GET', 'https://r.qzone.qq.com/fcg-bin/cgi_get_portrait.fcg?g_tk='.time().'&uins=' . $qq);     	 		 	 
    $http_post->send();    		 		   
    return iconv('GBK', 'UTF-8', trim($http_post->responseText, "portraitCallBack()"));    	 						
}    		    	 
    	  				 
