function Lucky_GetArticleTemplate($template,$file){       		  	
	global $zbp;    			 		  
    $GLOBALS['Filter_Plugin_Template_GetTemplate']['Lucky_GetArticleTemplate'] = PLUGIN_EXITSIGNAL_NONE;     			  		
    if($file=='header'){       	 		 
    	$GLOBALS['Filter_Plugin_Template_GetTemplate']['Lucky_GetArticleTemplate'] = PLUGIN_EXITSIGNAL_RETURN;    			  		 
    	return $zbp->usersdir . 'theme/Lucky/plugin/getArticleTemplate.php';     		     
    }     				   
}       	 	 	
    	  	 	 	
function Lucky_exclude_category(&$type,&$page,&$category,&$author,&$datetime,&$tag,&$w,&$pagebar){     		   		
	global $zbp;     	   	   
	if($type == 'index' || $type == 'author' || $type == 'date' || $type == 'tag'){      	  		 
		$ec_array = explode(',',$zbp->Config('Lucky')->exclude_category);    		  			 
		foreach ($ec_array as $key => $Catenew){         			
			$w[]=array('<>','log_CateID',$Catenew);    	  			 	
		}    	   				
		if($type == 'index'){    	 		    
			$pagebar = new Pagebar($zbp->option['ZC_INDEX_REGEX'], true, true);    	   	  	
		} elseif($type == 'tag'){    	 		   	
            if (isset($tag->ID)) {        	  	
                $tag = $zbp->GetTagByID($tag->ID);    	 	 	  	
            } else {    	 					 
                $tag = $zbp->GetTagByAliasOrName($tag->alias);     	 			  
            }    	 			 		
			$pagebar = new Pagebar($zbp->option['ZC_TAGS_REGEX']);     	 	 		 
            $pagebar->UrlRule->Rules['{%id%}'] = $tag->ID;      	  		 
            $pagebar->UrlRule->Rules['{%alias%}'] = $tag->Alias == '' ? rawurlencode($tag->Name) : $tag->Alias;     			 	 	
		} elseif ($type == 'author') {       	   	
			if (isset($author->ID)) {    						 	
                $author = $zbp->GetMemberByID($author->ID);     		 			 
            } else {      	 		 	
                $author = $zbp->GetMemberByNameOrAlias($author->Alias);      	   	 
            }     				 		
            $pagebar = new Pagebar($zbp->option['ZC_AUTHOR_REGEX']);      	 	 		
            $pagebar->UrlRule->Rules['{%id%}'] = $author->ID;    	  	 		 
            $pagebar->UrlRule->Rules['{%alias%}'] = $author->Alias == '' ? rawurlencode($author->Name) : $author->Alias;      	 		  
		}    	 	  			
		$pagebar->PageCount = $zbp->displaycount;     	 		   
		$pagebar->PageNow = $page;      		   	
		$pagebar->PageBarCount = $zbp->pagebarcount;       			 	
	}    		    	 
}    		      
    	 		 			
