    	$url = BuildSafeURL($zbp->host.'zb_system/cmd.php?act=verify');    	 		    
    	$zbp->footer .='<script type="text/javascript">$("#btnPosts").click(function() {var strUserName = $("#edtUserName").val();var strPassWord = $("#edtPassWord").val();var strSaveDate = $("#savedate").val();if ((strUserName == "") || (strPassWord == "")) { alert("'.$zbp->lang['error']['66'].'");return false; };$.ajax({ url: "'.$url.'",dataType: "html",data: { username: strUserName,password: MD5(strPassWord),savedate: strSaveDate},type: "POST",success: function(res) { location.href = "'.$zbp->host.'zb_system/admin/index.php?act=admin"; },error: function(ree) { if (ree.status == 500) { $(".login-error h4").show();$(".sign .containers").css("height", "330px");}}});return false;});$("#chkRemember").click(function() { $("#savedate").attr("value", $("#chkRemember").attr("checked") == "checked" ? 30 : 1); });</script>' . "\r\n";      		  		
	}       				 
