function Lucky_TimeAgo( $ptime ) {      			 	 
    $ptime = strtotime($ptime);         	 	
    $etime = time() - $ptime;      		 		 
    if($etime < 1) return 'åˆšåˆš';    		  	   
    $interval = array (    		   		 
        12 * 30 * 24 * 60 * 60  =>  'å¹´å‰ ('.date('Y-m-d', $ptime).')',     	 	   	
        30 * 24 * 60 * 60       =>  'ä¸ªæœˆå‰ ('.date('m-d', $ptime).')',    	  		   
        7 * 24 * 60 * 60        =>  'å‘¨å‰ ('.date('m-d', $ptime).')',       	  		
        24 * 60 * 60            =>  'å¤©å‰',    	  				 
        60 * 60                 =>  'å°æ—¶å‰',     			 		 
        60                      =>  'åˆ†é’Ÿå‰',     	  			 
        1                       =>  'ç§’å‰'    				 	 	
    );     	    	 
    foreach ($interval as $secs => $str) {    	  		   
        $d = $etime / $secs;    					   
        if ($d >= 1) {    							 
            $r = round($d);    	 	 	 	 
            return $r . $str;      	   	 
        }    			 	   
    };    	  		  	
}    	 		  	 
     			   	
function Lucky_Symbol($strContent){     		 	 	 
    global $zbp;      			 		
	$EmoticonsFaceList = "dog|smile|laugh|laughing|shy|naughty|laughs|happy|decline|anger|cry|crys|chagrin|awkward|spit|torment|despise|bye|shutup|nose|poor|abuse|right|left|zan|rose";     		  			
    $facelist=explode('|',$EmoticonsFaceList);    		   	  
    $emos=array();      	   		
    foreach ($facelist as $face){    		 	 			
        $emos['[F]'.$face.'[/F]']=''.$face.'.gif';     	 		   
    }     	 		   
	if(preg_match_all('/(\[F\])([a-zA-Z]+?)(\[\/F\])/',$strContent,$matches)){     	  	  	
		$matches = array_unique($matches[0]);    	     	 
		foreach ($matches as $data) {    		     	
		    if(isset($emos[$data])){    	    	  
				$strContent= str_replace($data,'<img title="'.$data.'" style="padding:2px;border:0;" src="'.Lucky_Host().'zb_users/theme/Lucky/source/face/'.$emos[$data].'"/>',$strContent);       	  	 
			}    	      	
		}       		 	 
	}    			 			 
    $Symbol=$strContent;    	  		   
	return $Symbol;      		    
}    			  			
    	   		  
