function Lucky_BuildModule_Avatarcomments() {    	 	 		  
	global $zbp;     		   	 
	$i = $zbp->modulesbyfilename['comments']->MaxLi;        		 	
	if ($i == 0) $i = 10;    		  				
	if ($zbp->Config('Lucky')->comm_admin == "a") {           	
		$comments = $zbp->GetCommentList('*', array(array('=', 'comm_IsChecking', 0),array('<>', 'comm_AuthorID','1')), array('comm_PostTime' => 'DESC'), $i, null);    			 	  	
	} else {    	   		  
		$comments = $zbp->GetCommentList('*', array(array('=', 'comm_IsChecking', 0)), array('comm_PostTime' => 'DESC'), $i, null);    	  	 			
	}        	 		
	$s = '<ul>';    	 	  	  
	foreach ($comments as $comment) {    		  	   
		$comment->Content=Lucky_Symbol($comment->Content);    		  	   
		$s .= '<li><div class="comment-info"><img src="'.Lucky_Host().'zb_users/theme/Lucky/style/image/grey.gif" data-original="'.$comment->Author->Avatar.'" class="sidebar_avatar" width="60" height="60" alt="'.$comment->Author->StaticName.'">'.$comment->Author->StaticName.'<span>' . $comment->Time('mæœˆdæ—¥') . '</span></div><div class="comment-excerpt"><p><a href="' . $comment->Post->Url .'#comment-'.$comment->ID.'" title="æŸ¥çœ‹è¢« '.$comment->Author->StaticName.' åæ§½è¿‡çš„é¡µé¢">' . TransferHTML($comment->Content, '[noenter]') . '</a></p></div></li>';     	  				
	}    	 		  	 
	$s .= '</ul>';    	    			
	return $s;    		    	 
}    	 	 	 	 
    		  	 	 
