function Lucky_Links() {    		 		   
	global $zbp,$modules;    		  	 		
	$content = '';    				   	
	if (Lucky_mobile()) {    		  				
		if ($zbp->Config('Lucky')->link_pc_kg == 'a') {       		   
			$content = $zbp->modulesbyfilename['link']->Content;          		
		}    	 	  	  
	} else {    	 	  	  
		if ($zbp->Config('Lucky')->link_mobile_kg == 'a') {    	   	  	
			$content = $zbp->modulesbyfilename['link']->Content.'<style>.footer_links {display: block!important;}#footer .themeauthor {text-align: left !important;}</style>';    	 		    
		}    	 	 			 
	}    		  		  
	return $content;    		 	 		 
}    	 		  	 
    		 					
function Lucky_mobile() {         		 
	global $zbp;     	 		  	
	$regex = '/android|adr|iphone|ipad|windows\sphone|kindle|gt\-p|gt\-n|rim\stablet|opera|meego/i';      		 	  
	//UCæµè§ˆå™¨æ˜¯å‚»é€¼ï¼    			 	 	 
	$mobile = false;    			  	 	
	if (GetVars('alwaystheme', 'COOKIE') == 'mobile') {    		    	 
		$mobile = true;     				  	
	}       	   	
	if (preg_match($regex, GetVars('HTTP_USER_AGENT', 'SERVER'))) {    	  		   
		$mobile = true;     	   		 
	}     	  				
	if (GetVars('alwaystheme', 'COOKIE') == 'pc') {    		 	 			
		$mobile = false;     			   	
	}     		 	 		
	if (!$mobile) {    	   		  
		return true;     	 		 	 
	}    	  	 			
}    			   	 
       	 	  
