function Lucky_baidu_recond_show($url){     					 	
	global $zbp;         	  
	if ($zbp->Config('Lucky')->check_bdurl !='a') return true;          		
	$data=array();    					 	 
	$http_post = Network::Create();      			  	
	$http_post->open('GET','http://www.baidu.com/s?wd='.$url);    			  			
	$http_post->setRequestHeader('Referer', substr($zbp->host, 0, -1) . $zbp->currenturl);    	 	    	
	$http_post->send($data);     			 	  
	$result = $http_post->responseText;    					   
