	}else{    	 		  		
		return '<a target="_blank" title="ç™¾åº¦å·²æ”¶å½•ï¼Œè½¬è½½è¯·æ³¨æ˜æ¥æºï¼Œè°¢è°¢~~" rel="external nofollow" href="http://www.baidu.com/s?wd='.$url.'"><i class="fa fa-smile-o"></i> ç™¾åº¦å·²æ”¶å½•</a>';      	 	 		
	}    		   		 
