function Lucky_baidu_recond_Page(&$template){    						  
	global $zbp;     	  				
	if ($zbp->Config('Lucky')->check_bdurl !='a') return true;     	 			  
	$article = $template->GetTags('article');        		  
	$str=Lucky_baidu_recond_show($article->Url);    			  	 	
	$template->SetTags('LuckyBaiduRecond',$str);     	  	  		
}    				   	
    	    			
