        break;
    case "tag":
        $addTitle = $tag->Metas->XF_Addtitle ?: "";
        $strTitle = $tag->Name.$addTitle."-".$zbp->name;
        if($page != 1) {
            $strTitle .= "-ç¬¬".$page."é¡µ";
        }
        break;
    case "date":
        if($page == 1) {
            $strTitle = $zbp->title."-".$zbp->name;
        } else {
            $tmpTitle = explode(" ", $zbp->title);
            $strTitle = $tmpTitle[0]."-".$zbp->name."-ç¬¬".$page."é¡µ";
        }
        break;
    case "article":
        $addTitle = $article->Metas->XF_Addtitle ?: "";
        $catTitle = $post_category=="a" ? "-".$article->Category->Name : "";
        $strTitle = $article->Title.$addTitle.$catTitle."-".$zbp->name;
        break;
    case "page":
        $addTitle = $article->Metas->XF_Addtitle ?: "";
        $subTitle = $page_subname=="a" ? "-".$zbp->subname : "";
        $strTitle = $article->Title.$addTitle."-".$zbp->name.$subTitle;
        break;
    default:
        $subTitle = $page_subname=="a" ? "-".$zbp->subname : "";
        $strTitle = $title."-".$zbp->name.$subTitle;
        break;
}

echo "<title>".$strTitle."</title>". "\r\n";

if($type && isset($Lucky_SEO)) {
	echo $Lucky_SEO;
}

{/php}', $templates['header']);
     	 	    
	}    	   				
}    	   		 	
     	  				
function Lucky_SEO_List(&$type,&$page,&$category,&$author,&$datetime,&$tag) {     		 		 	
	global $zbp;    		 		 		
	$result = $keywords = $description = '';       		   
	if($zbp->Config('Lucky')->seo=='a') {     	 		 	 
		if($type=='index'&&$page=='1') {       			  
			$keywords = $zbp->Config('Lucky')->keywords;       		   
			$description = $zbp->Config('Lucky')->description;        	   
		} elseif($type=='category') {      	   	 
			if($category->Metas->XF_Keywords) {      	 		  
				$keywords = $category->Metas->XF_Keywords;    	 		 		 
			} else {	    			   	 
				$keywords = $category->Name.','.$zbp->name;     		 	 	 
			}     		 	   
			if($category->Metas->XF_Description) {       	  	 
				$description = $category->Metas->XF_Description;    	 		  	 
			} else {	     		 		  
				$description = $zbp->name.','.$zbp->title;     	 	 			
			}     	 					
		} elseif($type=='tag') {    						 	
			if($tag->Metas->XF_Keywords) {    	     		
				$keywords = $tag->Metas->XF_Keywords;     	    	 
			} else {	    					 	 
				$keywords = $zbp->title.','.$zbp->name;       				 
			}    		    	 
			if($tag->Metas->XF_Description) {    		  			 
				$description = $tag->Metas->XF_Description;    			 		 	
			} else {    	  		   
				$description = $zbp->name.','.$zbp->title;    	     	 
			}    	   	 	 
		} else {    	  	  		
			$keywords = $zbp->title.','.$zbp->name;    					 		
			$description = $zbp->name.','.$zbp->title;     		  		 
		}    				 		 
		$result .=  '<meta name="keywords" content="'.htmlspecialchars($keywords).'" />' . "\r\n";    		 	 	  
		$result .= '<meta name="description" content="'.htmlspecialchars($description).'" />' . "\r\n";    		 	 	 	
	}      	   		
	$zbp->template->SetTags('Lucky_SEO',$result);    	  		   
}    	  	  		
     	  	   
function Lucky_SEO_POST(&$template) {     			 			
	global $zbp;      			  	
	$result = $keywords = $description = '';     	  	   
	$article = $template->GetTags('article');     	 		 		
	if($zbp->Config('Lucky')->seo == 'a'){    				 			
		if($article->Metas->XF_Keywords) {     		 	 	 
			$keywords = $article->Metas->XF_Keywords;    	  	   	
		} else {    	 	 	 	 
			$arrayTags = array();    				 	  
			if($article->Tags) {      					 
	          	foreach($article->Tags as $key) {     	  			 
	          		$arrayTags[] = $key->Name;    	 			 	 
	          	}      	  	  
			} else {    			 	  	
				$arrayTags[] = $article->Category->ID ? $article->Category->Name : $article->Title.','.$zbp->name;    	 	  		 
			}      			   
	        if($arrayTags) {    	  					
	        	$keywords = implode(',',$arrayTags);    	     		
	        }        	 	 
		}     	   		 
		if($article->Metas->XF_Description) {    	      	
			$description = $article->Metas->XF_Description;    	 		 		 
		} else {     	 	 	  
	  		$description = preg_replace('/[\r\n\s]+/', ' ', trim(SubStrUTF8(TransferHTML($article->Content,'[nohtml]'), 98)).'...');    	    			
			$description = str_replace('&nbsp;','',$description);    	   	   
			$description = str_replace(' ','',$description);      				 	
	  	}     	  	   
		$result .=  '<meta name="keywords" content="'.htmlspecialchars($keywords).'" />' . "\r\n";    	  		 		
		$result .= '<meta name="description" content="'.htmlspecialchars($description).'" />' . "\r\n";    		 		  	
	}      		    
	$template->SetTags('Lucky_SEO', $result);    	   				
}       			  